#[test]
fn test_32_bit_shifts_lose_bits_off_the_top_and_keep_the_sign() {
    // Operands are LOCALS: Go folds a constant shift at compile time and
    // refuses `1 << 31` as an int32 overflow, where a variable wraps.
    let one: i32 = 1;
    let three: i32 = 3;
    let neg: i32 = -16;
    crate::testport::assert_eq((one) << (4), 16, "1 << 4");
    crate::testport::assert_eq((one) << (31), -2147483648, "1 << 31 is the sign bit");
    crate::testport::assert_eq((three) << (30), -1073741824, "3 << 30 drops the top bit");
    crate::testport::assert_eq((neg) >> (2), -4, "arithmetic right shift keeps the sign");
    crate::testport::assert_eq((4096) >> (12), 1, "4096 >> 12");
}
